result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/prune.py", "content": """"Row-group statistics pruning for a single parquet file.

Reads ONLY the row groups whose min/max statistics (from
ParquetFile.metadata.row_group(i).column(...) stats) overlap the queried
range, then filters those groups exactly.
"""
from typing import List, Tuple, Union

import pyarrow as pa
import pyarrow.compute as pc
import pyarrow.parquet as pq

PathLike = Union[str, bytes]


class RowGroupPruner:
    """Range-query a parquet file using row-group min/max statistics."""

    def __init__(self, path: PathLike):
        self.path = path
        self.pf = pq.ParquetFile(path)
        md = self.pf.metadata
        # Map column name -> physical parquet column index (from row-group 0;
        # identical for every row group of this file).
        self._col_index = {
            md.row_group(0).column(j).path_in_schema: j
            for j in range(md.num_columns)
        }
        # Public counter: how many row groups were actually read.
        self.read_row_groups = 0

    @property
    def num_row_groups(self) -> int:
        return self.pf.metadata.num_row_groups

    def reset_counter(self) -> None:
        self.read_row_groups = 0

    def _overlaps(self, rg_index: int, column: str, lo, hi) -> bool:
        """True if row group's [min, max] stats may contain rows in [lo, hi]."""
        stats = (
            self.pf.metadata.row_group(rg_index)
            .column(self._col_index[column])
            .statistics
        )
        if stats is None or not stats.has_min_max:
            # No usable statistics -> cannot prune, must read the group.
            return True
        return not (stats.min > hi or stats.max < lo)

    def query_between(self, column: str, lo, hi) -> pa.Table:
        """Return rows where column BETWEEN lo AND hi, reading only the
        row groups whose statistics overlap [lo, hi]."""
        self.reset_counter()
        kept: List[pa.Table] = []
        for i in range(self.num_row_groups):
            if not self._overlaps(i, column, lo, hi):
                continue
            group = self.pf.read_row_group(i)
            self.read_row_groups += 1
            mask = pc.and_kleene(
                pc.greater_equal(group[column], lo),
                pc.less_equal(group[column], hi),
            )
            kept.append(group.filter(mask))
        schema = self.pf.schema_arrow
        if not kept:
            return schema.empty_table()
        return pa.concat_tables(kept)


def query_between(path: PathLike, column: str, lo, hi) -> Tuple[pa.Table, int]:
    """Convenience one-shot query; returns (result_table, row_groups_read)."""
    pruner = RowGroupPruner(path)
    return pruner.query_between(column, lo, hi), pruner.read_row_groups
